class ProfilePage extends StatefulWidget {
  const ProfilePage({super.key});

  @override
  State<ProfilePage> createState() => _ProfilePageState();
}

class _ProfilePageState extends State<ProfilePage> with SingleTickerProviderStateMixin {
  static final _tween = Tween<Alignment>(begin: Alignment.centerLeft, end: Alignment.centerRight);

  late ValueNotifier<AppThemeMode> _themeModeNotifier;

  StreamSubscription<AppThemeMode>? _themeModeSubscription;

  late final AnimationController _alignmentController;
  late Animation<AlignmentGeometry> _alignmentAnimation;

  @override
  void initState() {
    super.initState();
    _initThemeMode();
    _initAnimation();
  }

  @override
  void dispose() {
    _themeModeSubscription?.cancel();
    _themeModeNotifier.dispose();
    _alignmentController.dispose();
    super.dispose();
  }

  void _initThemeMode() {
    final SettingsRepository settings = context.read<SettingsRepository>();
    // Синхронное чтение начального значения.
    _themeModeNotifier = ValueNotifier(settings.readThemeMode());
    // Подписка на поток изменений режима темы для автообновления UI.
    _themeModeSubscription = settings.themeModeStream.listen(
      (AppThemeMode mode) => _themeModeNotifier.value = mode,
    );
  }

  void _initAnimation() {
    _alignmentController = AnimationController(
      duration: const Duration(seconds: 2),
      vsync: this,
    )..repeat(reverse: true);
    _alignmentAnimation = _tween.animate(_alignmentController);
  }

  @override
  Widget build(BuildContext context) {
    final ThemeFonts fonts = context.fonts;
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.profile)),
